🐛 Describe the bug
This standalone C++ program creates an optimizer with 3 param groups of a single tensor each. The tensor are initialized to 1. It also has default options that set the learning rate to 0, and the param groups are not setting their learning rate. It then computes a backward pass and runs an optimization step, printing the tensors modified by the optimizer:
#include <torch/torch.h>
#include <iostream>

using namespace torch;

int main() {
  Tensor input = torch::ones({1, 3});
  Tensor w = torch::ones({2, 3});
  Tensor b = torch::ones({1, 2});
  Tensor output;

  input.set_requires_grad(true);
  w.set_requires_grad(true);
  b.set_requires_grad(true);   

  std::vector<optim::OptimizerParamGroup> param_groups;

  // Param group for input tensor
  auto *input_adam_opts = new optim::AdamOptions();
  input_adam_opts->weight_decay(0.11);
  optim::OptimizerOptions *input_opts = input_adam_opts;
  param_groups.push_back(
    optim::OptimizerParamGroup(
      std::vector<Tensor>({input}),
      std::unique_ptr<optim::OptimizerOptions>(input_opts)
    )
  );

  // Param group for w tensor
  auto *w_adam_opts = new optim::AdamOptions();
  w_adam_opts->weight_decay(0.22);
  optim::OptimizerOptions *w_opts = w_adam_opts;
  param_groups.push_back(
    optim::OptimizerParamGroup(
      std::vector<Tensor>({w}),
      std::unique_ptr<optim::OptimizerOptions>(w_opts)
    )
  );

  // Param group for b tensor
  auto *b_adam_opts = new optim::AdamOptions();
  b_adam_opts->weight_decay(0.33);
  optim::OptimizerOptions *b_opts = b_adam_opts;
  param_groups.push_back(
    optim::OptimizerParamGroup(
      std::vector<Tensor>({b}),
      std::unique_ptr<optim::OptimizerOptions>(b_opts)
    )
  );

  // Default options and optimizer creation
  optim::AdamOptions default_opts;
  default_opts.lr(0);
  auto optimizer = optim::Adam(param_groups, default_opts);

  output = at::linear(input, w, b);
  Tensor outgrad = torch::ones({1, 2});
  output.backward(outgrad);

  optimizer.step();
  std::cout << "input:" << std::endl;
  std::cout << input << "\n";
  std::cout << "w:" << std::endl;
  std::cout << w << "\n";
  std::cout << "b:" << std::endl;
  std::cout << b << "\n";

  std::cout << "\n";

  std::vector<torch::optim::OptimizerParamGroup> retrieved_param_groups = 
    optimizer.param_groups();

  auto *group_0_opts = static_cast<torch::optim::AdamOptions*>(
    &(retrieved_param_groups[0].options())
  );
  std::cout << "input weight decay:\n";
  std::cout << group_0_opts->weight_decay() <<"\n";
  std::cout << "input learning rate:\n";
  std::cout << group_0_opts->lr() <<"\n";

  std::cout << "\n";

  auto *group_1_opts = static_cast<torch::optim::AdamOptions*>(
    &(retrieved_param_groups[1].options())
  );
  std::cout << "w weight decay:\n";
  std::cout << group_1_opts->weight_decay() <<"\n";
  std::cout << "w learning rate:\n";
  std::cout << group_1_opts->lr() <<"\n";

  std::cout << "\n";

  auto *group_2_opts = static_cast<torch::optim::AdamOptions*>(
    &(retrieved_param_groups[2].options())
  );
  std::cout << "b weight decay:\n";
  std::cout << group_2_opts->weight_decay() <<"\n";
  std::cout << "b learning rate:\n";
  std::cout << group_2_opts->lr() <<"\n";
}

The output is:
input:
 0.9990  0.9990  0.9990
[ CPUFloatType{1,3} ]
w:
 0.9990  0.9990  0.9990
 0.9990  0.9990  0.9990
[ CPUFloatType{2,3} ]
b:
 0.9990  0.9990
[ CPUFloatType{1,2} ]

input weight decay:
0.11
input learning rate:
0.001

w weight decay:
0.22
w learning rate:
0.001

b weight decay:
0.33
b learning rate:
0.001

So it can be seen that setting the learning rate to 0 in the default options is ignored, the tensor have changed after the step. And retrieving the param group options shows that they are using a learning rate of 0.001.
Versions
I have built from source using commit 23c0d2689e4b49858787adc6ca2c5032ac221b96. This is the cmake command:
cmake \
	-DCMAKE_BUILD_TYPE=Release \
	-DBUILD_PYTHON=False \
	-DCMAKE_INSTALL_PREFIX=$home_dir/torch \
	-DTORCH_BUILD_VERSION=2.6.0a0+git23c0d26 \
	-DUSE_NUMPY=False \

